import { inject, Injectable } from '@angular/core';
import { WindowService } from 'espd-common/window';

@Injectable()
export class ScrollService {

	private window = inject(WindowService);

	public scrollToTop(): void {
		this.window.nativeWindow.scrollTo(0, 0);
	}

	public scrollToYCoord(yCoord = 0): void {
		this.window.nativeWindow.scrollTo(0, yCoord);
	}

	public getTopOffset(elem: HTMLElement): number { // crossbrowser version
		const box = elem.getBoundingClientRect();

		const body = this.window.nativeWindow.document.body;
		const docEl = this.window.nativeWindow.document.documentElement;

		const scrollTop = this.window.nativeWindow.pageYOffset || docEl.scrollTop || body.scrollTop;

		const clientTop = docEl.clientTop || body.clientTop || 0;

		const top = box.top + scrollTop - clientTop;
		return Math.round(top);
	}
}